"""Render saved release evidence without network dependencies or model calls."""
import base64
import html
import json
import sys
from pathlib import Path

root = Path(sys.argv[1] if len(sys.argv) > 1 else '.artifacts/release-eval-v10')
probes = Path(sys.argv[2] if len(sys.argv) > 2 else '.artifacts/release-probes-v10')
out = Path(sys.argv[3] if len(sys.argv) > 3 else '/tmp/draftgpt-release-validation-20261020.html')
def load(path, fallback=None):
    return json.loads(path.read_text()) if path.exists() else fallback
def esc(value):
    return html.escape(str(value))
def details(title, value):
    return f'<details><summary>{esc(title)}</summary><pre>{esc(json.dumps(value, indent=2, ensure_ascii=False))}</pre></details>'
def card(c, trial):
    f = c['face']; image = root / trial / (c['slotId']+'.jpg')
    pic = f'<img alt="Illustration for {esc(f["name"])}" loading="lazy" src="data:image/jpeg;base64,{base64.b64encode(image.read_bytes()).decode()}">' if image.exists() else ''
    stats = f'<strong>{f["power"]}/{f["toughness"]}</strong>' if f['type'] == 'Creature' else ''
    return f'''<article class="card" data-search="{esc(f['name']+' '+f['type']+' '+f['rules_text'])}">{pic}<div class="cardbody"><small>{esc(c['slotId'])} · {esc(f['rarity'])}</small><h4>{esc(f['name'])} <span>{esc(f['mana_cost'])}</span></h4><p class="type">{esc(f['type'])} — {esc(f['subtype'])}</p><p class="rules">{esc(f['rules_text'])}</p>{stats}<p class="flavor">{esc(f['flavor_text'])}</p><details><summary>Art direction and tokens</summary><p>{esc(f['art_direction'])}</p><pre>{esc(json.dumps(c['tokens'],ensure_ascii=False))}</pre></details></div></article>'''
