distribution = load(root/'distribution.json', {'results': [], 'limitation': 'Not run'})
reviews = load(probes/'reviews.json', [])
observed = load(probes/'observed.json', {})
worlds = load(probes/'worlds.json', [])
audit = load(probes/'audit.json', {})
inventories = load(root/'inventory-audit.json', {})
corrected = load(probes.parent/'release-calibration-corrected-v11'/'reviews.json', [])
rows = ''.join(f'''<tr><th><a href="#{esc(r['trial']['id'])}">{esc(r['trial']['id'])}</a></th><td>{len(r['designs'])}/{r['trial']['total']}</td><td>{'Interrupted' if r.get('interrupted') else 'Passed' if r['ready'] else 'Blocked'}</td><td>{f'{r["durationMs"]/60000:.1f} min' if r.get('durationMs') is not None else 'Interrupted — excluded'}{' (resumed; exclude)' if r.get('durationMs') is not None and not r['latencyComparable'] else ''}</td><td>${r['estimatedTextCost']:.4f}</td><td>{len(r['revised'])}</td><td>{sum(i['severity']!='minor' for i in r['finalReview']['issues']) if r.get('finalReview') else 'Not reached'}</td></tr>''' for r in results)
sections = ''
for r in results:
    trial=r['trial']['id']; b=r.get('blueprint') or {}; w=b.get('world',{})
    art=load(root/trial/'art.json', {})
    diagnostic=load(root/trial/'diagnostic-pack.json', {})
    pack=r['pack'] or diagnostic.get('pack', [])
    art_note=f"<p>Diagnostic pack art: {sum(bool(x.get('success')) for x in art.get('images', []))}/{len(art.get('images', []))} images, {art.get('durationMs', 0)/1000:.1f}s. This is separate from text workflow timing and does not approve a rejected candidate.</p>"+details('Art allowance, deadline and results', art) if art else ''
    phases=''.join(f'<div class="phase"><strong>{esc(p["stage"])}</strong><span>{p["durationMs"]/1000:.1f}s</span></div>' for p in r['phases'])
    issues = (r.get('finalReview') or {}).get('issues', [])
    issue_list=''.join(f'<li><strong>{esc(i["severity"])} · {esc(", ".join(i["slots"]))}</strong><p>{esc(i["evidence"])}</p><p>Correction: {esc(i["correction"])}</p></li>' for i in issues)
    sections+=f'''<section id="{esc(trial)}"><p class="eyebrow">{esc(trial)} · {'MODEL GATE PASSED' if r['ready'] else 'NOT DRAFT-READY'}</p><h2>{esc(w.get('name',trial))}</h2><p class="lead">{esc(w.get('premise',''))}</p><p>{esc(w.get('description',''))}</p><p><strong>Conflict.</strong> {esc(w.get('conflict',''))}</p><div class="phases">{phases}</div><p>{esc(r.get('error') or (r.get('finalReview') or {}).get('summary','No final review'))}</p>{details('Full world, color identities, archetypes and mechanics',b)}<h3>Final review</h3><ul>{issue_list or ('<li>No remaining issues reported. This is not a guarantee of balance.</li>' if r.get('finalReview') else '<li>Final review was not reached. No acceptance verdict is available.</li>')}</ul>{details('Earlier reviews and coordinated edit plan',{'reviews':r['reviews'],'editPlan':r.get('editPlan')})}<h3>{"One diagnostic fifteen-card pack" if pack else "No pack available"}</h3><p>Seed {r['trial']['seed']}. Rejected candidates are shown for inspection and are not published by the app. Diagnostic packs may come from structurally invalid or interrupted inventories; they do not change the saved verdict. Full inventories remain below.</p>{art_note}<div class="cards">{''.join(card(c,trial) for c in pack)}</div><details><summary>Inspect all {len(r['designs'])} designs and fixed slots</summary><div class="cards inventory">{''.join(card(c,trial) for c in r['designs'])}</div>{details('Fixed slots',r['slots'])}</details></section>'''
simrows=''.join(f'''<tr><th>{esc(r['id'])}</th><td>{r['players']}</td><td>{r['packsChecked']:,}</td><td>{r['metrics']['uniqueDesigns']['median']:.0f}</td><td>{r['metrics']['repeatedCopies']['median']:.0f}</td><td>{r['metrics']['fixingLands']['median']:.0f}</td><td>{100*r['mythicFraction']:.2f}%</td></tr>''' for r in distribution['results'])
world_html=''.join(f'''<details><summary>{esc(x['id'])} · {esc((x.get('blueprint') or {}).get('world',{}).get('name',x.get('error','Failed')))}</summary><p><strong>Ideas:</strong> {esc(' / '.join(x['ideas']) or '(empty)')}</p><p>{esc((x.get('blueprint') or {}).get('world',{}).get('premise',''))}</p>{details('Full response and direction',x)}</details>''' for x in worlds)
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DraftGPT — release validation</title><style>
:root{color-scheme:dark;--bg:#12181d;--panel:#1c252d;--ink:#edf1ed;--muted:#aebdbd;--accent:#e4bd73}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 system-ui,sans-serif}header,main,footer{max-width:1280px;margin:auto;padding:36px 28px}header{border-bottom:1px solid #46545b}h1,h2,h3{line-height:1.2}h1{font:clamp(36px,5vw,66px)/1.1 Georgia,serif;max-width:900px}h2{font:36px Georgia,serif}h3{margin-top:36px}h4{margin:8px 0}a{color:var(--accent)}.eyebrow,small{color:var(--accent);font-size:12px;letter-spacing:.07em}.lead{font-size:21px;max-width:950px}p{max-width:1000px}.muted{color:var(--muted)}nav{display:flex;flex-wrap:wrap;gap:18px;margin-top:24px}section{padding:35px 0;border-bottom:1px solid #46545b;scroll-margin:20px}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left}th,td{padding:12px;border-bottom:1px solid #46545b;white-space:nowrap}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:20px 0}.card{border:1px solid #54616a;border-radius:10px;background:var(--panel);overflow:hidden}.cardbody{padding:19px}.card img{width:100%;display:block}.card h4 span{display:block;color:var(--accent);font-size:15px;margin-top:5px}.rules{white-space:pre-line}.type,details,.flavor{font-size:14px}.flavor{font-style:italic;color:var(--muted)}summary{cursor:pointer;padding:12px 0;color:var(--accent)}details{overflow-wrap:anywhere}pre{white-space:pre-wrap;font:13px/1.5 ui-monospace,monospace;background:#0d1216;padding:18px;max-height:600px;overflow:auto}details>p{margin-left:12px}.phases{display:flex;flex-wrap:wrap;gap:8px}.phase{display:flex;flex-direction:column;background:var(--panel);padding:12px 18px;font-size:14px}.notice{border-left:4px solid var(--accent);background:var(--panel);padding:16px 24px}input{padding:10px;background:var(--panel);color:var(--ink);border:1px solid #758591;max-width:100%;width:420px}label{display:block;margin-bottom:6px}:focus-visible{outline:3px solid var(--accent);outline-offset:3px}.card[hidden]{display:none}li{margin:16px 0}@media(max-width:850px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:550px){header,main,footer{padding:24px 16px}.cards{grid-template-columns:1fr}h2{font-size:29px}}@media print{:root{color-scheme:light;--bg:white;--panel:#f6f6f6;--ink:black;--muted:#444;--accent:#62400b}body{font-size:11pt}.card{break-inside:avoid}nav,input,label{display:none}pre{max-height:none}}
</style><header><p class="eyebrow">DRAFTGPT / ENGINEERING ACCEPTANCE / 20–21 OCTOBER 2026</p><h1>Complete sets, measured before release.</h1><p class="lead">Original prompt-10 candidates and fresh prompt-11 follow-ups across Default, Busted, 135 and 270 cards. The final publication gate remains enforced.</p><div class="notice">__VERDICT__ Text workflow timings exclude art, Convex scheduling and browser delivery. These evaluations are not human playtests.</div><nav><a href="#results">Results</a><a href="#distribution">Distribution</a><a href="#calibration">Reviewer calibration</a><a href="#worlds">World input corpus</a>__NAV__</nav></header><main><section id="results"><h2>What completed, and what passed.</h2><p><strong>Hold quality acceptance.</strong> Four completed candidates failed their gates; two others were interrupted. The follow-up Busted set retains two duplicate-name groups. Default retains mechanic-contract issues, including a reviewer correction that incorrectly adds Flashback to a creature.</p><p>The later pipeline 3 fix preserves deterministic duplicate-name issues through edit planning and repairs names within a response. It is integration-tested; the paid results below predate it and remain unchanged. Local checks: 136 tests, typecheck, lint and build.</p><p><strong>Reviewer progress is partial.</strong> The corrected fixture run found four clear defects in all sixteen opportunities. Stale sacrifice-cost and sunrise claims disappeared in the separate regression sample, but reference comparisons still produced factual errors. Undefined-X ground truth was withdrawn; original zero-mana fixture metadata errors remain visible.</p><p><strong>World diversity remains weak.</strong> All twelve blueprints contain concrete supernatural causes, yet at least nine return to institutional control of magical resources. Names and bodily-trait-transfer premises repeat. This is not creative-quality acceptance.</p><p><strong>Release status.</strong> No production deploy. DNS verification needs Cloudflare access; real production acceptance needs Google-authenticated users. The legacy deck export is preserved. Human playtesting was excluded.</p><div class="tablewrap"><table><thead><tr><th>Candidate</th><th>Designs</th><th>Final gate</th><th>Time to outcome</th><th>Text estimate</th><th>Edited</th><th>Major/blocker issues</th></tr></thead><tbody>__ROWS__</tbody></table></div><p class="muted">Original candidates remain visible alongside the labeled prompt-11 intervention. Interrupted runs are excluded from latency comparisons. A rejected run may stop earlier than a successful run. Seeds match the direction selection within each size, not stochastic model outputs. Prices are usage estimates, not an invoice. Interrupted calls retain conservative uncertain-cost reservations; they are not reported as measured billable usage. Cached or resumed times are explicitly excluded.</p><label for="search">Filter cards by name, type or rules text</label><input id="search" type="search" placeholder="For example: draw, artifact, flashback"><p id="filter-status" role="status"></p></section><section id="distribution"><h2>Three rounds, across 1,000 seeds per configuration.</h2><div class="tablewrap"><table><thead><tr><th>Inventory</th><th>Players</th><th>Packs checked</th><th>Median unique</th><th>Median repeated copies</th><th>Median fixing lands</th><th>Mythic packs</th></tr></thead><tbody>__SIMROWS__</tbody></table></div><p>Every checked pack has fifteen distinct slot IDs, ten commons, four uncommons, one rare or mythic, and a monocolor common of each color. Repeated copies across packs are intentional. Some rejected inventories retain duplicate names; see packsWithRepeatedNames in the metrics.</p><p>__SIMLIMIT__</p>__SIMDETAILS____INVENTORIES__</section><section id="calibration"><h2>Can the reviewer explain the actual defect?</h2><p>Twelve fresh editorial fixtures, two repetitions per power mode. Expected answers were frozen outside provider requests. Audit reasons separately: attaching any issue to a card does not establish correct detection.</p>__AUDIT____REVIEWS__</section><section id="worlds"><h2>Twelve different input bundles.</h2><p>Empty, fantastical, contradictory, abstract, humorous, repeated and instruction-like ideas. Structural success is separate from semantic variety and literal writing.</p>__WORLDS__</section>__SECTIONS__<section id="method"><h2>Reproduce and inspect.</h2><p>Saved calls contain exact prompts, settings, parsed outputs, usage, repair feedback and durations. Source hashes and pipeline versions are frozen in config.json. The app's planner, parser, repair and collation functions drive this runner; scheduler and player flows are tested separately.</p>__CONFIG__<p><a href="https://developers.openai.com/api/docs/guides/evaluation-best-practices">OpenAI evaluation guidance</a> · <a href="https://developers.openai.com/api/docs/models/gpt-6-luna">Luna model documentation</a></p></section></main><footer>Offline review artifact. No external fonts, scripts, image requests or telemetry.</footer><script>const box=document.getElementById('search');box.addEventListener('input',()=>{const q=box.value.toLowerCase();let visible=0;document.querySelectorAll('.card').forEach(c=>{c.hidden=!c.dataset.search.toLowerCase().includes(q);if(!c.hidden)visible++});document.getElementById('filter-status').textContent=q?visible+' matching card displays (pack and inventory copies)':'';});</script></html>'''
values={'VERDICT': f"{sum(r['ready'] for r in results)} of {len(results)} recorded candidates passed the automatic final gate; {sum(bool(r.get('interrupted')) for r in results)} were interrupted.", 'NAV':''.join(f'<a href="#{esc(r["trial"]["id"])}">{esc(r["trial"]["id"])}</a>' for r in results), 'ROWS':rows,'SIMROWS':simrows,'SIMLIMIT':esc(distribution['limitation']),'SIMDETAILS':details('All exposure metrics, including pair assignments and role/text proxies',distribution),'INVENTORIES':details('Complete inventory audit: validation, duplicate designs, curves and mechanic observations',inventories),'AUDIT':details('Reason-by-reason inspection',audit),'REVIEWS':details('Corrected calibration outputs (zero-mana slot metadata repaired)',corrected)+details('Original calibration outputs (contains zero-mana slot metadata errors)',reviews)+details('Separate observed-failure regression outputs (not held out)',observed),'WORLDS':world_html,'SECTIONS':sections,'CONFIG':details('Frozen configuration',data['config'])}
for key,value in values.items(): page=page.replace('__'+key+'__',value)
out.write_text(page)
print(out, len(page), 'characters')
